import static org.hamcrest.Matchers.is;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.mockito.Mock;
import org.mockito.Mockito;

public class CommentsConfigurationTest {

    @Test
    public void constructorShouldCreateANewCommentsConfiguration() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        assertThat(configuration, Mockito.spy(null));
    }

    @Test
    public void constructorWithCommentsMapShouldCreateACopiesOfTheInputMap() {
        Map<String, List<String>> commentsMap = new HashMap<>();
        commentsMap.put("key1", new ArrayList<>());
        commentsMap.put("key2", new ArrayList<>());

        CommentsConfiguration configuration = new CommentsConfiguration(commentsMap);
        assertThat(configuration.getComments(), is(commentsMap));
    }

    @Test
    public void setCommentShouldAddNewLines() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration configuration = new CommentsConfiguration();
        String[] commentLines = {"line1", "line2"};

        Mockito.when(configuration.getComments()).thenReturn(comments);

        configuration.setComment("path", commentLines[0], commentLines[1]);
        assertThat(configuration.getComments().get("path"), is(List.of(commentLines)));
    }

    @Test
    public void setCommentShouldAddNewLineWithNoMarker() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration configuration = new CommentsConfiguration();
        String[] commentLines = {"line1", "line2"};

        Mockito.when(configuration.getComments()).thenReturn(comments);

        configuration.setComment("path", "", commentLines[0]);
        assertThat(configuration.getComments().get("path"), is(List.of(commentLines)));
    }

    @Test
    public void getAllCommentsShouldReturnUnmodifiableMap() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("key1", new ArrayList<>());
        comments.put("key2", new ArrayList<>());

        CommentsConfiguration configuration = new CommentsConfiguration(comments);
        Map<String, List<String>> result = configuration.getAllComments();

        assertThat(result, is(comments));
        assertThat(result, Mockito.spyIsNotModified());
    }

    @Test
    public void getAllCommentsShouldReturnUnmodifiableList() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("key1", new ArrayList<>());

        CommentsConfiguration configuration = new CommentsConfiguration();
        Map<String, @UnmodifiableView List<String>> result = configuration.getAllComments();

        assertThat(result.get("key1"), is(@UnmodifiableView Mockito.spyList()));
    }
}
